function severify(signals) {
  if (signals.moneyWrong || signals.dataLeak || signals.activeAbuse) return { sev: 1, page: true };
  if (signals.qualityDrop || signals.costSpike || signals.featureDown) return { sev: 2, page: true };
  return { sev: 3, page: false };
}
const cases = [
  [{ moneyWrong: true }, 1, true],
  [{ dataLeak: true }, 1, true],
  [{ qualityDrop: true }, 2, true],
  [{ costSpike: true }, 2, true],
  [{ latencyDrift: true }, 3, false],
];
let pass = 0;
for (const [sig, sev, page] of cases) {
  const r = severify(sig);
  if (r.sev === sev && r.page === page) pass++;
  else console.log('MISS ' + JSON.stringify(sig));
}
console.log(pass + '/' + cases.length + ' severities correct');

